from django.core.management.base import BaseCommand
from django.utils import timezone
from datetime import timedelta
from portal.models import Publication,Course
NEWS = [
('ai-assistants','ИИ-ассистенты: от ответа на вопрос к работе над задачей','tools','Что меняется, когда нейросеть получает доступ к инструментам, файлам и последовательности действий.'),
('local-models','Нейросеть на своём компьютере: зачем запускать модели локально','tools','Разбираем сценарии, в которых важны автономность и контроль над данными.'),
('code-review','Второй взгляд на код: как ИИ помогает замечать ошибки','code','Где полезны подсказки модели и почему проверка разработчика остаётся необходимой.'),
('visual-workflow','От идеи до изображения: как устроен процесс работы с генерацией','creative','Референсы, описание задачи и последовательные правки вместо случайных запросов.'),
('team-ai','ИИ в команде: какие задачи стоит автоматизировать первыми','business','Начать с повторяющихся операций и оценить результат на небольшом пилоте.'),
('model-evaluation','Как сравнивать нейросети на своих задачах','tools','Почему набор реальных примеров полезнее одного впечатляющего ответа.'),
('video-ai','Генерация видео: что продумать до первого запроса','creative','Сценарий, движение камеры и визуальная последовательность коротких сцен.'),
('data-quality','Качество данных: незаметная часть успешного ИИ-проекта','business','Как неполные инструкции и противоречивые документы влияют на результат.'),
('python-ai','Python и ИИ: как собрать небольшой прототип','code','Начинаем с понятной задачи, входных данных и проверяемого результата.'),
('search-ai','Поиск с ИИ: как проверять найденную информацию','tools','Смотрим первоисточник, дату публикации и контекст утверждений.'),
('design-ai','Нейросети в дизайне: от наброска к осмысленному решению','creative','Как использовать варианты модели, сохраняя единый стиль проекта.'),
('workflow-ai','Один процесс вместо десяти сервисов: выбираем рабочий инструмент','business','Оцениваем интеграции, стоимость и удобство на конкретном сценарии.')]
ARTICLES = [
('prompt-guide','Как написать понятный запрос к нейросети','tools','Пять составляющих хорошего запроса: задача, контекст, данные, ограничения и формат.'),
('python-start','Первый проект с ИИ на Python: план для начинающих','code','Небольшая задача, аккуратная работа с ключами и проверка ответов.'),
('ai-fact-check','Как проверять ответы ИИ и не пропускать ошибки','business','Практическая привычка: отделять проверяемые факты от предположений.')]
class Command(BaseCommand):
    help = 'Create clearly labeled demo content; existing records are never overwritten.'
    def handle(self,*args,**kwargs):
        for kind,rows in [('news',NEWS),('article',ARTICLES)]:
            for i,(slug,title,topic,summary) in enumerate(rows):
                body = summary + '\n\nНачните с конкретной задачи\nОпишите результат, который хотите получить, и подготовьте небольшой пример. Это позволит понять, где инструмент помогает, а где требуется дополнительная проверка.\n\nПроверьте результат\nСопоставьте ответ с исходными данными. Обратите внимание на пропуски, неточные формулировки и неподтверждённые выводы. Для важных утверждений найдите первоисточник.\n\nПрименяйте постепенно\nИспытайте подход на ограниченном наборе задач. Сравните затраченное время и качество результата, прежде чем менять весь рабочий процесс.\n\nЭтот текст создан для демонстрации структуры публикации. Перед настоящим запуском редакция заменит его авторским материалом.'
                Publication.objects.get_or_create(slug=slug,defaults=dict(title=title,kind=kind,topic=topic,summary=summary,body=body,published=True,demo=True,featured=(i==0 and kind=='news'),published_at=timezone.now()-timedelta(hours=i*5)))
        rows=[('ai-basics','ИИ с нуля: инструменты для повседневных задач','tools','beginner',0,'2 недели'),('work-ai','Нейросети для работы и продуктивности','business','beginner',4900,'4 недели'),('python-llm','Python и языковые модели','code','intermediate',12900,'8 недель'),('creative-ai','Визуальный контент с нейросетями','creative','beginner',6900,'5 недель'),('prompt-practice','Практика запросов к нейросетям','tools','beginner',0,'1 неделя'),('ai-process','Автоматизация процессов с ИИ','business','intermediate',15900,'6 недель')]
        for slug,title,direction,level,price,duration in rows:
            Course.objects.get_or_create(slug=slug,defaults=dict(title=title,provider='НЕЙРО · пример программы',summary='Освойте основные подходы и закрепите навыки на небольшом практическом проекте.',audience='Для тех, кто хочет разобраться в инструментах искусственного интеллекта и применять их в своих задачах.',program='Знакомство с инструментами и постановка задачи\nРабота с входными данными\nПрактические сценарии и проверка результата\nСамостоятельный итоговый проект',direction=direction,level=level,price=price,duration=duration,published=True,demo=True))
        self.stdout.write(self.style.SUCCESS('Demo content is ready.'))
